# Multi-term search for DRAWING NUMBER, DESCRIPTION and DISCIPLINE.
# Separate terms with spaces, commas or semicolons; quotes preserve phrases.
def parse_search_terms(search_text):
    terms = [
        quoted if quoted else plain
        for quoted, plain in re.findall(r'"([^"]+)"|([^,\s;]+)', search_text.strip())
    ]
    return [term.strip() for term in terms if term.strip()]


def apply_multi_term_search(frame, column, search_text):
    terms = parse_search_terms(search_text)
    if not terms:
        return frame

    # OR logic: keep a row if the field contains at least one entered term.
    pattern = "|".join(re.escape(term) for term in terms)
    return frame[
        frame[column].astype(str).str.contains(
            pattern, case=False, regex=True, na=False
        )
    ].copy()


